[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "recipe_surface_bolognese",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "recipe_surface_bolognese",
      "value": {
        "ingredients": [
          {
            "name": "Olive Oil",
            "quantity": "30 ml (2 tbsp)"
          },
          {
            "name": "Pancetta, diced",
            "quantity": "100 g"
          },
          {
            "name": "Yellow Onion, finely chopped",
            "quantity": "150 g (1 medium)"
          },
          {
            "name": "Carrot, finely chopped",
            "quantity": "100 g (1 medium)"
          },
          {
            "name": "Celery Stalk, finely chopped",
            "quantity": "100 g (1-2 stalks)"
          },
          {
            "name": "Ground Beef (80/20)",
            "quantity": "300 g"
          },
          {
            "name": "Ground Pork",
            "quantity": "200 g"
          },
          {
            "name": "Whole Milk",
            "quantity": "200 ml"
          },
          {
            "name": "Dry White Wine",
            "quantity": "200 ml"
          },
          {
            "name": "Canned Crushed Tomatoes",
            "quantity": "400 g"
          },
          {
            "name": "Tomato Paste",
            "quantity": "30 g (2 tbsp)"
          },
          {
            "name": "Beef Broth (or water)",
            "quantity": "250 ml"
          },
          {
            "name": "Salt",
            "quantity": "5 g (1 tsp) + to taste"
          },
          {
            "name": "Freshly Ground Black Pepper",
            "quantity": "2 g (1/2 tsp) + to taste"
          },
          {
            "name": "Freshly Grated Nutmeg",
            "quantity": "1 g (1/4 tsp)"
          }
        ],
        "instructions": [
          {
            "title": "Prepare the Soffritto:",
            "description": "Heat the olive oil in a large, heavy-bottomed pot or Dutch oven over medium heat. Add the diced pancetta and cook until crispy and its fat has rendered, about 5-7 minutes. Remove the crispy pancetta with a slotted spoon and set aside, leaving the rendered fat in the pot."
          },
          {
            "title": "Sauté Vegetables:",
            "description": "Add the finely chopped onion, carrot, and celery (the \"soffritto\") to the pot. Cook over medium-low heat, stirring occasionally, until the vegetables are very soft and translucent, about 10-15 minutes. Do not let them brown."
          },
          {
            "title": "Brown the Meats:",
            "description": "Increase the heat to medium. Add the ground beef and ground pork to the pot. Break up the meat with a spoon and cook until it is fully browned and no pink remains, about 8-10 minutes. Drain off any excess fat if necessary."
          },
          {
            "title": "Deglaze with Milk and Wine:",
            "description": "Pour in the whole milk and bring to a gentle simmer. Cook, stirring occasionally, until the milk has almost completely evaporated and been absorbed by the meat, about 10-15 minutes. This step adds richness and tenderizes the meat. Next, add the dry white wine. Bring to a simmer and cook until the wine has almost completely evaporated, about 5-7 minutes."
          },
          {
            "title": "Add Tomatoes and Broth:",
            "description": "Stir in the crushed tomatoes, tomato paste, beef broth, salt, pepper, and nutmeg. Return the crispy pancetta to the pot. Bring the sauce to a gentle simmer."
          },
          {
            "title": "Slow Simmer:",
            "description": "Once simmering, reduce the heat to very low, cover the pot partially (leaving a small gap for steam to escape), and let the sauce gently simmer for at least 3 hours. Stir the sauce every 30-45 minutes to prevent sticking and ensure even cooking. If the sauce becomes too thick during simmering, add a splash more beef broth or water. The goal is a thick, rich sauce."
          },
          {
            "title": "Finish and Serve:",
            "description": "After 3 hours, the sauce should be deeply colored, thick, and incredibly flavorful. Taste and adjust seasoning (salt, pepper, or nutmeg) if needed. Serve hot with your favorite pasta, traditionally tagliatelle, and a generous grating of Parmigiano-Reggiano cheese."
          }
        ]
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "recipe_surface_bolognese",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium"
          },
          "children": [
            {
              "id": "title",
              "type": "Text",
              "properties": {
                "text": "Traditional Italian Bolognese Sauce (Serves 4)",
                "style": "headline"
              }
            },
            {
              "id": "summary_card",
              "type": "Card",
              "children": [
                {
                  "id": "summary_col",
                  "type": "Column",
                  "properties": {
                    "spacing": "small"
                  },
                  "children": [
                    {
                      "id": "summary_title",
                      "type": "Text",
                      "properties": {
                        "text": "**Summary**",
                        "style": "title"
                      }
                    },
                    {
                      "id": "summary_text",
                      "type": "Text",
                      "properties": {
                        "text": "This recipe provides a traditional, rich, and deeply flavorful Bolognese sauce, perfect for serving with fresh pasta. The key to its authentic taste is a slow, patient simmer over three hours, allowing the flavors to meld beautifully. This process creates a thick, luxurious sauce that is a staple of Italian cuisine."
                      }
                    }
                  ]
                }
              ]
            },
            {
              "id": "image_row",
              "type": "Row",
              "properties": {
                "spacing": "medium",
                "mainAxisAlignment": "spaceBetween"
              },
              "children": [
                {
                  "id": "image_simmering",
                  "type": "Image",
                  "properties": {
                    "src": "/bolognese_simmering.jpg",
                    "alt": "Bolognese sauce simmering in a pot.",
                    "aspectRatio": 1
                  }
                },
                {
                  "id": "image_soffritto",
                  "type": "Image",
                  "properties": {
                    "src": "/soffritto_ingredients.jpg",
                    "alt": "Finely chopped onion, carrot, and celery for a soffritto.",
                    "aspectRatio": 1
                  }
                }
              ]
            },
            {
              "id": "content_tabs",
              "type": "Tabs",
              "children": [
                {
                  "id": "ingredients_tab",
                  "type": "Tab",
                  "properties": {
                    "label": "Ingredients"
                  },
                  "children": [
                    {
                      "id": "ingredients_list",
                      "type": "List",
                      "properties": {
                        "children": "{{@data.ingredients}}"
                      },
                      "template": {
                        "id": "ingredient_item_template",
                        "type": "ListItem",
                        "children": [
                          {
                            "id": "ingredient_row",
                            "type": "Row",
                            "properties": {
                              "mainAxisAlignment": "spaceBetween"
                            },
                            "children": [
                              {
                                "id": "ingredient_name",
                                "type": "Text",
                                "properties": {
                                  "text": "{{@item.name}}"
                                }
                              },
                              {
                                "id": "ingredient_quantity",
                                "type": "Text",
                                "properties": {
                                  "text": "{{@item.quantity}}"
                                }
                              }
                            ]
                          }
                        ]
                      }
                    }
                  ]
                },
                {
                  "id": "instructions_tab",
                  "type": "Tab",
                  "properties": {
                    "label": "Instructions"
                  },
                  "children": [
                    {
                      "id": "instructions_list",
                      "type": "List",
                      "properties": {
                        "listStyle": "numbered",
                        "children": "{{@data.instructions}}"
                      },
                      "template": {
                        "id": "instruction_item_template",
                        "type": "ListItem",
                        "children": [
                          {
                            "id": "instruction_text",
                            "type": "Text",
                            "properties": {
                              "text": "**{{@item.title}}** {{@item.description}}"
                            }
                          }
                        ]
                      }
                    }
                  ]
                }
              ]
            },
            {
              "id": "divider",
              "type": "Divider"
            },
            {
              "id": "actions_row",
              "type": "Row",
              "properties": {
                "spacing": "medium",
                "mainAxisAlignment": "spaceEvenly"
              },
              "children": [
                {
                  "id": "button_pairings",
                  "type": "Button",
                  "properties": {
                    "label": "Find Pasta Pairings"
                  },
                  "action": {
                    "type": "functionCall",
                    "call": "openUrl",
                    "arguments": {
                      "url": "https://example.com/pasta-pairings"
                    }
                  }
                },
                {
                  "id": "button_shop",
                  "type": "Button",
                  "properties": {
                    "label": "Shop Bolognese Ingredients Online"
                  },
                  "action": {
                    "type": "functionCall",
                    "call": "openUrl",
                    "arguments": {
                      "url": "https://example.com/shop-bolognese-ingredients"
                    }
                  }
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
